<script setup lang="ts">
import type { WorkspaceSummary } from '~/server/geo-outcome-model/types'

definePageMeta({ layout: 'owner' })
useHead({ title: 'GEO 模型｜DiscoveryStack', meta: [{ name: 'robots', content: 'noindex,nofollow,noarchive' }] })

const { data, error, pending, refresh } = await useFetch<{ status: string, workspace: WorkspaceSummary }>('/api/geo-outcome-model/workspace', { server: false })
const workspace = computed(() => data.value?.workspace || null)
const isUnauthorized = computed(() => (error.value as { statusCode?: number } | null)?.statusCode === 401)
const readinessClass = (ready: boolean, status: string) => ready ? 'status status--good' : status === 'gate_blocked' ? 'status status--blocked' : 'status status--warn'
type ModelOpsView = { ownerUserId: number, policy: { policyId: string, status: string, cadence: string, minimumNewVerifiedCandidates: number, minimumNewQueryGroups: number, minimumNewWebsites: number, minimumObservationSpanDays: number, allowedModelFamilies: string[], maximumTrainingRunsPerCycle: number, cooldownHours: number, shadowEvaluationEnabled: boolean, autonomousExecutionEnabled: boolean, expiresAt: string | null } | null, cycles: Array<{ cycleId: string, status: string, trigger: string, eligibleCandidateCount: number, reasonCodes: string[], trainingRunId: string | null, modelArtifactId: string | null, createdAt: string, completedAt: string | null }>, events: Array<{ eventId: string, cycleId: string, eventType: string, eventPayload: Record<string, unknown>, createdAt: string }>, shadowEvaluations: Array<{ evaluationId: string, artifactId: string, status: string, candidateCount: number, positiveCount: number, negativeCount: number, queryGroupCount: number, websiteCount: number, reasonCodes: string[], evaluationWindowStart: string, evaluationWindowEnd: string }>, rollbackDecisions: Array<{ decisionId: string, artifactId: string, rollbackArtifactHash: string, reason: string, createdAt: string }>, outcome: { readiness: { development: { ready: boolean, status: string, missing: string[] }, shadow: { ready: boolean, status: string, missing: string[] } }, datasets: Array<{ manifestId: string, status: string, taskType: string, positiveCount: number, hardNegativeCount: number, websiteCount: number, queryGroupCount: number, trainRowCount: number, validationRowCount: number, testRowCount: number, temporalHoldoutRowCount: number, manifestFingerprint: string, limitations: string[] }>, trainingRuns: Array<{ trainingRunId: string, status: string, modelFamily: string, datasetManifestId: string, artifactId: string | null, reason: string | null }>, models: Array<{ artifactId: string, artifactHash: string, modelFamily: string, status: string, trainingRowCount: number }>, datasetDecisions: Array<{ manifestId: string, newStatus: string, reason: string }>, modelDecisions: Array<{ artifactId: string, newStatus: string, reason: string }> } }
const { data: modelOpsData, error: modelOpsError, pending: modelOpsPending, refresh: refreshModelOps } = await useFetch<{ status: string, workspace: ModelOpsView }>('/api/geo-outcome-model/modelops/workspace', { server: false })
const modelOps = computed(() => modelOpsData.value?.workspace || null)
const modelOpsSaving = ref(false)
const modelOpsSuccess = ref('')
const modelOpsActionError = ref('')
const idempotencyKey = () => `ui-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
async function policyAction(action: 'enable' | 'pause' | 'revoke') { if (!modelOps.value?.policy) return; modelOpsSaving.value = true; modelOpsSuccess.value = ''; modelOpsActionError.value = ''; try { await $fetch(`/api/geo-outcome-model/modelops/policies/${modelOps.value.policy.policyId}/${action}`, { method: 'POST', body: { idempotencyKey: idempotencyKey(), reason: `Owner workbench ${action} action.` } }); modelOpsSuccess.value = `Policy ${action} request completed.`; await refreshModelOps() } catch (error) { modelOpsActionError.value = error instanceof Error ? error.message : 'Policy action failed.' } finally { modelOpsSaving.value = false } }
async function reviewDataset(manifestId: string, decision: 'approve' | 'revoke') { modelOpsSaving.value = true; modelOpsSuccess.value = ''; modelOpsActionError.value = ''; try { await $fetch(`/api/geo-outcome-model/datasets/${manifestId}/review`, { method: 'POST', body: { idempotencyKey: idempotencyKey(), decision, reason: `Owner workbench dataset ${decision}.` } }); modelOpsSuccess.value = `Dataset ${decision} request completed.`; await Promise.all([refresh(), refreshModelOps()]) } catch (error) { modelOpsActionError.value = error instanceof Error ? error.message : 'Dataset review failed.' } finally { modelOpsSaving.value = false } }
async function reviewModel(artifactId: string, decision: 'approve_for_shadow' | 'revoke') { modelOpsSaving.value = true; modelOpsSuccess.value = ''; modelOpsActionError.value = ''; try { await $fetch(`/api/geo-outcome-model/models/${artifactId}/review`, { method: 'POST', body: { idempotencyKey: idempotencyKey(), decision, reason: `Owner workbench model ${decision}.` } }); modelOpsSuccess.value = `Model ${decision} request completed.`; await Promise.all([refresh(), refreshModelOps()]) } catch (error) { modelOpsActionError.value = error instanceof Error ? error.message : 'Model review failed.' } finally { modelOpsSaving.value = false } }
async function runCycle() { modelOpsSaving.value = true; modelOpsSuccess.value = ''; modelOpsActionError.value = ''; try { await $fetch('/api/geo-outcome-model/modelops/cycles/run', { method: 'POST', body: { idempotencyKey: idempotencyKey() } }); modelOpsSuccess.value = modelOps.value?.policy?.autonomousExecutionEnabled ? 'Policy-driven experimental cycle completed or stopped with a durable gate result.' : 'Owner-review cycle completed or is awaiting a durable approval gate.'; await Promise.all([refresh(), refreshModelOps()]) } catch (error) { modelOpsActionError.value = error instanceof Error ? error.message : 'ModelOps cycle failed.' } finally { modelOpsSaving.value = false } }
</script>

<template>
  <main class="geo-model-page">
    <section class="hero">
      <div>
        <NuxtLink class="back-link" to="/audit-lab">← 返回私有稽核實驗室</NuxtLink>
        <p class="eyebrow">OWNER-ONLY · GEO OUTCOME MODEL FOUNDATION V1</p>
        <h1>GEO 模型<br><em>學習可觀測的 outcome。</em></h1>
        <p class="lede">這裡管理 DiscoveryStack 自己的 outcome model foundation：Query × Candidate Page × Engine × Model / Interface × Locale × Run × Timestamp。這不是 Qwen 微調，也不是一個把所有訊號折疊成單一 GEO 分數的展示頁。</p>
      </div>
      <div class="hero-note"><strong>治理界線</strong><span>Policy-driven mode 可在一次 owner authorization 後自動完成 governed dataset、training 與 shadow；任何 experimental prediction 都不是已驗證的引用結果，且沒有 production_active。</span><button type="button" @click="refresh()">重新載入</button></div>
    </section>

    <section v-if="pending" class="state-card"><strong>Loading</strong><span>正在讀取 owner-scoped GEO model workspace。</span></section>
    <section v-else-if="isUnauthorized" class="state-card state-card--blocked"><strong>Unauthorized · owner-only</strong><span>這個工作台只接受既有 owner session，不會接受 browser 提交的 owner ID。</span></section>
    <section v-else-if="error" class="state-card state-card--error"><strong>Error · workspace unavailable</strong><span>{{ error.message || '目前無法載入 workspace。' }}</span><small>若尚未配置 private administration 或 durable database，狀態會 fail closed；不會以假資料代替。</small></section>
    <template v-else-if="workspace">
      <section class="section-block modelops-shell">
        <div class="section-heading"><div><p class="eyebrow">MODEL OPS AUTOMATION V1</p><h2>Governed owner workbench</h2></div><span class="status status--neutral">{{ modelOps?.policy?.autonomousExecutionEnabled ? 'EXPERIMENTAL AUTONOMOUS' : 'OWNER GATED · NO PRODUCTION MODEL' }}</span></div>
        <div v-if="modelOpsPending" class="state-card"><strong>Loading · ModelOps</strong><span>正在讀取 durable policy、cycle、shadow與activity ledger。</span></div>
        <div v-else-if="modelOpsError" class="state-card state-card--error"><strong>Error · ModelOps unavailable</strong><span>{{ modelOpsError.message || '目前無法載入 ModelOps workspace。' }}</span><small>沒有 durable database 或 owner session 時 fail closed；不以假資料或 production fallback 代替。</small></div>
        <div v-else-if="!modelOps" class="state-card state-card--blocked"><strong>Blocked · ModelOps not configured</strong><span>尚未建立 owner-scoped automation policy。建立 policy 後仍然預設 paused，不能自動核准 dataset 或 model。</span></div>
        <template v-else>
          <div class="modelops-grid">
            <article class="panel"><p class="eyebrow">01 · AUTOMATION POLICY</p><h3>Policy authorization</h3><div v-if="!modelOps.policy" class="empty-card">Empty · 尚未建立 policy。</div><template v-else><div class="gate-row"><span>Status</span><span :class="readinessClass(modelOps.policy.status === 'enabled', modelOps.policy.status === 'revoked' ? 'gate_blocked' : modelOps.policy.status)">{{ modelOps.policy.status }}</span></div><dl class="detail-list"><div><dt>Cadence</dt><dd>{{ modelOps.policy.cadence }}</dd></div><div><dt>Thresholds</dt><dd>{{ modelOps.policy.minimumNewVerifiedCandidates }} candidates · {{ modelOps.policy.minimumNewQueryGroups }} query groups · {{ modelOps.policy.minimumNewWebsites }} websites · {{ modelOps.policy.minimumObservationSpanDays }} days</dd></div><div><dt>Training</dt><dd>{{ modelOps.policy.allowedModelFamilies.join(', ') }} · max {{ modelOps.policy.maximumTrainingRunsPerCycle }} / cycle</dd></div><div><dt>Cooldown / expiry</dt><dd>{{ modelOps.policy.cooldownHours }} hours · {{ modelOps.policy.expiresAt || 'none' }}</dd></div></dl><div class="button-row"><button type="button" :disabled="modelOpsSaving || modelOps.policy.status === 'revoked' || modelOps.policy.status === 'enabled'" @click="policyAction('enable')">Enable</button><button type="button" :disabled="modelOpsSaving || modelOps.policy.status !== 'enabled'" @click="policyAction('pause')">Pause</button><button type="button" class="danger-button" :disabled="modelOpsSaving || modelOps.policy.status === 'revoked'" @click="policyAction('revoke')">Revoke</button><button type="button" :disabled="modelOpsSaving || modelOps.policy.status !== 'enabled'" @click="runCycle">Run policy cycle</button></div></template><p class="plain-copy">{{ modelOps.policy?.autonomousExecutionEnabled ? '已啟用一次性 owner-approved autonomous execution：dataset approval 與 shadow admission 會留下 machine actor ledger；artifact 仍只停留在 experimental shadow，degradation 會 stop。' : '目前為 owner-gated mode：dataset approval、model shadow approval 與 rollback 仍需 owner decision。' }}</p></article>
            <article class="panel"><p class="eyebrow">02 · READINESS</p><h3>重新計算的候選資料</h3><div class="readiness-grid"><div><span>Development</span><strong>{{ modelOps.outcome.readiness.development.ready ? 'READY' : modelOps.outcome.readiness.development.status }}</strong><small>{{ modelOps.outcome.readiness.development.missing.length ? modelOps.outcome.readiness.development.missing.join(' · ') : '所有 foundation gate 已滿足。' }}</small></div><div><span>Shadow</span><strong>{{ modelOps.outcome.readiness.shadow.ready ? 'READY' : modelOps.outcome.readiness.shadow.status }}</strong><small>{{ modelOps.outcome.readiness.shadow.missing.length ? modelOps.outcome.readiness.shadow.missing.join(' · ') : '所有 shadow gate 已滿足。' }}</small></div></div><p class="plain-copy">每個 cycle 都重新讀取 durable verified consumer-surface observations；provider API、GSC、GA4、heuristic與secondary資料不會成為 primary citation truth。</p></article>
          </div>
          <div v-if="modelOpsSuccess" class="inline-success" role="status">{{ modelOpsSuccess }}</div><div v-if="modelOpsActionError" class="inline-error" role="alert">{{ modelOpsActionError }}</div><div v-if="modelOpsSaving" class="saving-note">Saving · 正在等待 durable owner mutation 完成。</div>
          <article class="panel workbench-panel"><div class="section-heading"><div><p class="eyebrow">03 · CYCLE LEDGER</p><h3>Durable cycles</h3></div><span class="status status--neutral">{{ modelOps.cycles.length }} cycles</span></div><div v-if="!modelOps.cycles.length" class="empty-card">Empty · 尚未執行 cycle；dry-run 不會建立 cycle。</div><div v-else class="table-wrap"><table><thead><tr><th>Cycle</th><th>Status</th><th>Eligible</th><th>Training / artifact</th><th>Reason</th></tr></thead><tbody><tr v-for="cycle in modelOps.cycles" :key="cycle.cycleId"><td><strong>{{ cycle.cycleId }}</strong><small>{{ cycle.trigger }} · {{ cycle.createdAt }}</small></td><td><span :class="readinessClass(cycle.status === 'completed', cycle.status === 'blocked' || cycle.status === 'failed' ? 'gate_blocked' : cycle.status)">{{ cycle.status }}</span></td><td>{{ cycle.eligibleCandidateCount }}</td><td><small>{{ cycle.trainingRunId || '—' }}</small><small>{{ cycle.modelArtifactId || '—' }}</small></td><td>{{ cycle.reasonCodes.join(', ') || '—' }}</td></tr></tbody></table></div></article>
          <article class="panel workbench-panel"><div class="section-heading"><div><p class="eyebrow">04 · DATASET QUEUE</p><h3>Immutable dataset candidates</h3></div><span class="status status--neutral">{{ modelOps.policy?.autonomousExecutionEnabled ? 'policy-driven approval' : 'manual approval' }}</span></div><div v-if="!modelOps.outcome.datasets.length" class="empty-card">Empty · 尚未建立 immutable dataset candidate。</div><div v-else class="table-wrap"><table><thead><tr><th>Manifest</th><th>Status / readiness</th><th>Rows</th><th>Owner action</th></tr></thead><tbody><tr v-for="dataset in modelOps.outcome.datasets" :key="dataset.manifestId"><td><strong>{{ dataset.manifestId }}</strong><small>{{ dataset.taskType }} · {{ dataset.manifestFingerprint.slice(0, 18) }}…</small></td><td><span :class="readinessClass(dataset.status === 'approved', dataset.status)">{{ dataset.status }}</span><small>{{ dataset.limitations.slice(0, 2).join(' · ') }}</small></td><td>{{ dataset.trainRowCount }} train · {{ dataset.validationRowCount }} val · {{ dataset.testRowCount }} test · {{ dataset.temporalHoldoutRowCount }} temporal<br>+{{ dataset.positiveCount }} / −{{ dataset.hardNegativeCount }} · {{ dataset.queryGroupCount }} queries · {{ dataset.websiteCount }} sites</td><td><div v-if="dataset.status === 'ready_for_review'" class="button-row"><button type="button" :disabled="modelOpsSaving" @click="reviewDataset(dataset.manifestId, 'approve')">Approve</button><button type="button" class="danger-button" :disabled="modelOpsSaving" @click="reviewDataset(dataset.manifestId, 'revoke')">Revoke</button></div><span v-else class="plain-copy">{{ modelOps.policy?.autonomousExecutionEnabled ? 'Policy decision recorded or gate is terminal.' : 'No automatic decision.' }}</span></td></tr></tbody></table></div></article>
          <div class="modelops-grid"><article class="panel"><p class="eyebrow">05 · TRAINING RUNS</p><h3>Training gate</h3><div v-if="!modelOps.outcome.trainingRuns.length" class="empty-card">Empty · 只有 owner-approved dataset 才能建立 training run。</div><div v-for="run in modelOps.outcome.trainingRuns" :key="run.trainingRunId" class="run-row"><div><strong>{{ run.trainingRunId }}</strong><small>{{ run.modelFamily }} · dataset {{ run.datasetManifestId }}</small></div><span :class="readinessClass(run.status === 'completed', run.status === 'blocked' || run.status === 'failed' ? 'gate_blocked' : run.status)">{{ run.status }}</span><small v-if="run.reason" class="reason">{{ run.reason }}</small></div><p class="plain-copy">fit 僅使用 train partition；holdout 只做 evaluation。failure 不會保留半完成 artifact。</p></article><article class="panel"><p class="eyebrow">06 · MODEL REGISTRY</p><h3>Owner shadow approval</h3><div v-if="!modelOps.outcome.models.length" class="empty-card">Empty · artifact 只能在 training 完成後產生。</div><div v-for="model in modelOps.outcome.models" :key="model.artifactId" class="model-row"><div><strong>{{ model.artifactId }}</strong><small>{{ model.modelFamily }} · {{ model.trainingRowCount }} train rows · {{ model.artifactHash.slice(0, 18) }}…</small></div><span :class="readinessClass(model.status === 'approved_for_shadow', model.status === 'shadow_failed' || model.status === 'revoked' ? 'gate_blocked' : model.status)">{{ model.status }}</span><div v-if="model.status === 'ready_for_owner_review'" class="button-row"><button type="button" :disabled="modelOpsSaving" @click="reviewModel(model.artifactId, 'approve_for_shadow')">Approve shadow</button><button type="button" class="danger-button" :disabled="modelOpsSaving" @click="reviewModel(model.artifactId, 'revoke')">Revoke</button></div></div><p class="plain-copy">{{ modelOps.policy?.autonomousExecutionEnabled ? 'Artifact 可由 owner policy admitted_to_shadow；仍不存在 production_active，shadow degradation 會 stop 並提示 rollback。' : 'Artifact 不會自動 approved_for_shadow，也不存在 production_active。' }}</p></article></div>
          <div class="modelops-grid"><article class="panel"><p class="eyebrow">07 · SHADOW EVALUATION</p><h3>New-only observations</h3><div v-if="!modelOps.shadowEvaluations.length" class="empty-card">Empty · {{ modelOps.policy?.autonomousExecutionEnabled ? 'policy cycle 通過 artifact admission 後建立 shadow evaluation。' : 'owner approve artifact 後才會建立 shadow evaluation。' }}</div><div v-for="evaluation in modelOps.shadowEvaluations" :key="evaluation.evaluationId" class="evaluation-row"><div><strong>{{ evaluation.evaluationId }}</strong><small>{{ evaluation.evaluationWindowStart }} → {{ evaluation.evaluationWindowEnd }}</small></div><span :class="readinessClass(evaluation.status === 'completed', evaluation.status === 'needs_owner_attention' ? 'gate_blocked' : evaluation.status)">{{ evaluation.status }}</span><small>{{ evaluation.candidateCount }} candidates · +{{ evaluation.positiveCount }} / −{{ evaluation.negativeCount }} · {{ evaluation.queryGroupCount }} queries · {{ evaluation.websiteCount }} sites</small><small>{{ evaluation.reasonCodes.join(', ') || 'No alert reason.' }}</small></div><p class="plain-copy">training overlap、zero prediction class、0/0 null metric與severe regression會保留為明確診斷；嚴重 regression 只會暫停 eligibility並提示 owner rollback。</p></article><article class="panel"><p class="eyebrow">08 · ACTIVITY LEDGER</p><h3>Append-only history</h3><div v-if="!modelOps.events.length" class="empty-card">Empty · 尚未有 cycle event。</div><div v-for="activity in modelOps.events" :key="activity.eventId" class="activity-row"><strong>{{ activity.eventType }}</strong><small>{{ activity.cycleId }} · {{ activity.createdAt }}</small><code>{{ Object.entries(activity.eventPayload).map(([key, value]) => `${key}=${value}`).join(' · ') || 'redacted payload' }}</code></div></article></div>
          <div class="blocked-callout"><strong>Safe boundary</strong><span>此工作台沒有真實 provider、GSC、GA4、consumer UI、customer-site write、付款、部署或 production activation。所有結果都保留 owner review與可追溯 lineage。</span></div>
        </template>
      </section>
      <section class="section-block">
        <div class="section-heading"><div><p class="eyebrow">01 · DATA ASSETS</p><h2>資料資產總覽</h2></div><span class="status status--neutral">OWNER {{ workspace.ownerUserId }}</span></div>
        <div class="metric-grid">
          <article v-for="metric in [
            ['Structural auxiliary', workspace.inventory.structuralAuxiliaryCount, '可用於結構輔助 baseline'],
            ['Outcome observations', workspace.inventory.outcomeObservationsCount, '已接收的去識別 observation'],
            ['Verified primary', workspace.inventory.verifiedPrimaryCount, 'manual / consumer verified'],
            ['Provider secondary', workspace.inventory.providerSecondaryCount, '不得直接成為 citation truth'],
            ['Positive', workspace.inventory.positiveCount, 'citation observed'],
            ['Hard negative', workspace.inventory.hardNegativeCount, '同 run candidate set only'],
            ['Websites / queries', `${workspace.inventory.websiteCount} / ${workspace.inventory.queryCount}`, 'site / normalized query'],
            ['Engines / span', `${workspace.inventory.engineCount} / ${workspace.inventory.observationSpanDays ?? '—'} d`, 'engine-interface / time span'],
          ]" :key="metric[0]" class="metric-card"><span>{{ metric[0] }}</span><strong>{{ metric[1] }}</strong><small>{{ metric[2] }}</small></article>
        </div>
        <div class="notice"><strong>資料 inventory：</strong> repository 內有一份 101 筆 development proof-of-concept result 文件，但其 JSONL、checkpoint、raw labels、consent/PII ledger 與 V1 feature contract 未在 repository/DB 中可驗證，屬 <code>documentation_only</code>；250 筆 external dataset 則為 <code>{{ workspace.inventory.externalDatasetStatus }}</code>。兩者都未被匯入或冒充 citation outcome。</div>
      </section>

      <section class="section-block two-col">
        <article class="panel"><p class="eyebrow">02 · READINESS</p><h2>Outcome model readiness</h2><div class="gate-row"><span>Development gate</span><span :class="readinessClass(workspace.readiness.development.ready, workspace.readiness.development.status)">{{ workspace.readiness.development.ready ? 'READY' : workspace.readiness.development.status.toUpperCase() }}</span></div><p v-if="!workspace.readiness.development.ready" class="plain-copy">尚未達 V1 development policy。這些是治理門檻，不是普遍科學定律。</p><ul v-if="workspace.readiness.development.missing.length"><li v-for="item in workspace.readiness.development.missing" :key="item">{{ item }}</li></ul><div class="gate-row"><span>Shadow gate</span><span :class="readinessClass(workspace.readiness.shadow.ready, workspace.readiness.shadow.status)">{{ workspace.readiness.shadow.ready ? 'READY' : 'INSUFFICIENT_DATA' }}</span></div><p class="plain-copy">Shadow / promotion 使用更嚴格的 candidates、query groups、websites、engines、positives、verified hard negatives、時間跨度與 evidence policy。</p></article>
        <article class="panel"><p class="eyebrow">FUNNEL · NEVER COLLAPSED</p><h2>可分開學習的 outcome</h2><div class="funnel"><span>01 eligibility / indexability</span><span>02 observable candidate</span><span>03 retrieval</span><span>04 citation selection</span><span>05 citation absorption / answer influence</span><span>06 brand mention</span><span>07 recommendation</span></div><p class="plain-copy">沒有 verified observation 時不產生「未引用」負樣本；provider API、GSC、GA4 與 heuristic label 都維持正確的 secondary / aggregate / auxiliary 邊界。</p></article>
      </section>

      <section class="section-block"><div class="section-heading"><div><p class="eyebrow">03 · DATASET MANIFESTS</p><h2>Immutable manifests</h2></div><span class="status status--neutral">{{ workspace.datasets.length }} manifests</span></div><div v-if="!workspace.datasets.length" class="empty-card">Empty · 尚未建立 dataset manifest。建立 API 不會自動 approve。</div><div v-else class="table-wrap"><table><thead><tr><th>Manifest</th><th>Status</th><th>Task</th><th>Rows</th><th>Splits</th><th>Fingerprint</th></tr></thead><tbody><tr v-for="dataset in workspace.datasets" :key="dataset.manifestId"><td><strong>{{ dataset.manifestId }}</strong><small>{{ dataset.createdAt }}</small></td><td><span :class="readinessClass(dataset.status === 'approved', dataset.status)">{{ dataset.status }}</span></td><td>{{ dataset.taskType }}</td><td>{{ dataset.sourceObservationFingerprints.length }} · +{{ dataset.positiveCount }} / −{{ dataset.hardNegativeCount }}</td><td>tr {{ dataset.trainFingerprints.length }} · val {{ dataset.validationFingerprints.length }} · test {{ dataset.testFingerprints.length }} · temporal {{ dataset.temporalHoldoutFingerprints.length }}</td><td><code>{{ dataset.manifestFingerprint.slice(0, 18) }}…</code></td></tr></tbody></table></div></section>

      <section class="section-block two-col"><article class="panel"><p class="eyebrow">04 · TRAINING RUNS</p><h2>Deterministic baseline</h2><div v-if="!workspace.trainingRuns.length" class="empty-card">Empty · 尚未建立 training run。</div><div v-for="run in workspace.trainingRuns" :key="run.trainingRunId" class="run-row"><div><strong>{{ run.modelFamily }}</strong><small>{{ run.trainingRunId }}</small></div><span :class="readinessClass(run.status === 'completed', run.status === 'blocked' ? 'gate_blocked' : run.status)">{{ run.status }}</span><small v-if="run.reason" class="reason">{{ run.reason }}</small></div><p class="plain-copy">固定排序、固定初始化、bounded epochs / rows / features、L2；不使用 network、provider、GPU、Math.random 或 timestamp-dependent weights。</p></article><article class="panel"><p class="eyebrow">05 · MODEL REGISTRY</p><h2>Registry 與 rollback lineage</h2><div v-if="!workspace.models.length" class="empty-card">Empty · 尚未產生 model artifact。</div><div v-for="model in workspace.models" :key="model.artifactId" class="model-row"><div><strong>{{ model.modelFamily }}</strong><small>{{ model.artifactId }} · {{ model.trainingRowCount }} rows</small></div><span :class="readinessClass(model.status === 'approved_for_shadow', model.status === 'revoked' ? 'gate_blocked' : model.status)">{{ model.status }}</span><code>{{ model.artifactHash.slice(0, 18) }}…</code></div><p class="plain-copy">未提供 production_active 狀態。撤銷是 terminal；owner decision 以 append-only ledger 保存。</p></article></section>

      <section class="section-block"><div class="section-heading"><div><p class="eyebrow">06 · DECISION LEDGER</p><h2>Owner review history</h2></div><span class="status status--neutral">append-only</span></div><div v-if="!workspace.decisions.length" class="empty-card">Empty · 尚未有 owner decision。</div><div v-else class="table-wrap"><table><thead><tr><th>Decision</th><th>Transition</th><th>Reason</th><th>Artifact / dataset lineage</th></tr></thead><tbody><tr v-for="decision in workspace.decisions" :key="decision.decisionId"><td><strong>{{ decision.decisionId }}</strong><small>{{ decision.createdAt }}</small></td><td>{{ decision.previousStatus }} → {{ decision.newStatus }}</td><td>{{ decision.reason }}</td><td><code>{{ decision.artifactHash.slice(0, 14) }}…</code><small><code>{{ decision.datasetManifestHash.slice(0, 14) }}…</code></small></td></tr></tbody></table></div></section>

      <section class="section-block prediction-panel"><p class="eyebrow">07 · EXPERIMENTAL PREDICTION</p><h2>這不是實際引用結果</h2><p class="lede">Prediction API 只在 approved_for_shadow artifact 下提供 experimental_prediction；回應包含 artifact / dataset lineage、feature contributions、missing features 與 limitations，不會承諾排名提升、引用保證、流量、轉換或 ROI。</p><div class="prediction-badges"><span class="status status--warn">predictionIsVerifiedOutcome: false</span><span class="status status--blocked">production model: NOT READY</span><span class="status status--neutral">external provider calls: NONE</span></div></section>
    </template>
    <section v-else class="state-card"><strong>Empty</strong><span>目前沒有可呈現的 owner workspace 資產。</span></section>
